/**
 * Unit tests for JacksonAnnotationIntrospector.findRootName
 */
public class JacksonAnnotationIntrospector_findRootName_TriageGen0Test {

    private JacksonAnnotationIntrospector introspector;
    private AnnotatedClass annotatedClass;

    @Before
    public void setUp() {
        introspector = new JacksonAnnotationIntrospector();
        annotatedClass = Mockito.mock(AnnotatedClass.class);
    }

    /**
     * Tests the case where the @JsonRootName annotation is not present.
     * Covers the branch: if (ann == null) { return null; }
     */
    @Test
    public void testFindRootName_NoAnnotation() {
        // Mock _findAnnotation to return null
        // Since _findAnnotation is protected and called internally, 
        // we rely on the fact that the default introspector won't find it 
        // unless we provide a mock or a real class with the annotation.
        // However, since we cannot easily override protected methods in a spy without complexity,
        // we simulate the behavior by ensuring the mock AnnotatedClass doesn't trigger annotation detection.

        // In Jackson's actual implementation, _findAnnotation searches the annotated class.
        // We need to mock the behavior of the introspector's internal call.
        // Because _findAnnotation is protected, we use a spy to control its output.
        JacksonAnnotationIntrospector spyIntrospector = Mockito.spy(introspector);
        when(spyIntrospector._findAnnotation(annotatedClass, JsonRootName.class)).thenReturn(null);

        PropertyName result = spyIntrospector.findRootName(annotatedClass);

        assertNull("Should return null when annotation is missing", result);
    }

    /**
     * Tests the case where @JsonRootName is present with a value and a non-empty namespace.
     * Covers the successful path: return PropertyName.construct(ann.value(), ns);
     */
    @Test
    public void testFindRootName_WithAnnotationAndNamespace() {
        JsonRootName mockAnn = Mockito.mock(JsonRootName.class);
        when(mockAnn.value()).thenReturn("root");
        when(mockAnn.namespace()).thenReturn("http://example.com");

        JacksonAnnotationIntrospector spyIntrospector = Mockito.spy(introspector);
        when(spyIntrospector._findAnnotation(annotatedClass, JsonRootName.class)).thenReturn(mockAnn);

        PropertyName result = spyIntrospector.findRootName(annotatedClass);

        assertEquals("root", result.getName());
        assertEquals("http://example.com", result.getNamespace());
    }

    /**
     * Tests the case where @JsonRootName is present with a value and a null namespace.
     * Covers the path where ns is null.
     */
    @Test
    public void testFindRootName_WithAnnotationAndNullNamespace() {
        JsonRootName mockAnn = Mockito.mock(JsonRootName.class);
        when(mockAnn.value()).thenReturn("root");
        when(mockAnn.namespace()).thenReturn(null);

        JacksonAnnotationIntrospector spyIntrospector = Mockito.spy(introspector);
        when(spyIntrospector._findAnnotation(annotatedClass, JsonRootName.class)).thenReturn(mockAnn);

        PropertyName result = spyIntrospector.findRootName(annotatedClass);

        assertEquals("root", result.getName());
        assertNull("Namespace should be null", result.getNamespace());
    }

    /**
     * Tests the case where @JsonRootName is present with a value and an empty namespace string.
     * Covers the branch: if (ns != null && ns.length() == 0) { ns = null; }
     */
    @Test
    public void testFindRootName_WithAnnotationAndEmptyNamespace() {
        JsonRootName mockAnn = Mockito.mock(JsonRootName.class);
        when(mockAnn.value()).thenReturn("root");
        when(mockAnn.namespace()).thenReturn("");

        JacksonAnnotationIntrospector spyIntrospector = Mockito.spy(introspector);
        when(spyIntrospector._findAnnotation(annotatedClass, JsonRootName.class)).thenReturn(mockAnn);

        PropertyName result = spyIntrospector.findRootName(annotatedClass);

        assertEquals("root", result.getName());
        assertNull("Empty namespace should be converted to null", result.getNamespace());
    }
}
